from pathlib import Path
p=Path('ClockTimer.js')
s=p.read_text()
needle='''            return result;\n        }\n\n        get status() {'''
insert='''            return result;\n        }\n\n        fromJSON(json) {\n            if (this.status !== "ready") {\n                return false;\n            }\n\n            try {\n                const data =\n                    typeof json === "string"\n                        ? JSON.parse(json)\n                        : json;\n\n                if (\n                    !data ||\n                    typeof data !== "object" ||\n                    Array.isArray(data) ||\n                    data.tripId === null ||\n                    !Number.isInteger(data.tripId) ||\n                    typeof data.creationDate !== "string" ||\n                    typeof data.standardTime !== "string" ||\n                    typeof data.scheduledStart !== "string" ||\n                    !Array.isArray(data.records)\n                ) {\n                    return false;\n                }\n\n                const events = [];\n\n                for (const record of data.records) {\n                    if (\n                        !record ||\n                        typeof record !== "object" ||\n                        Array.isArray(record)\n                    ) {\n                        return false;\n                    }\n\n                    const entries = Object.entries(record);\n\n                    if (entries.length !== 1) {\n                        return false;\n                    }\n\n                    const [time, value] = entries[0];\n\n                    if (\n                        !value ||\n                        typeof value !== "object" ||\n                        Array.isArray(value) ||\n                        typeof value.type !== "string" ||\n                        !value.type.trim()\n                    ) {\n                        return false;\n                    }\n\n                    const date = new Date(time.replace(" ", "T"));\n\n                    if (Number.isNaN(date.getTime())) {\n                        return false;\n                    }\n\n                    events.push({ time, value });\n                }\n\n                const startIndex = events.findIndex(\n                    event => event.value.type === "start"\n                );\n                const endIndex = events.findIndex(\n                    event => event.value.type === "end"\n                );\n\n                if (startIndex < 0 || endIndex < 0) {\n                    return false;\n                }\n\n                if (!this.start({\n                    tripId: data.tripId,\n                    creationTime: `${data.creationDate} 00:00:00.000`,\n                    standardTime: data.standardTime,\n                    scheduledStart: data.scheduledStart,\n                    startTime: events[startIndex].time\n                })) {\n                    return false;\n                }\n\n                for (\n                    let index = startIndex + 1;\n                    index < endIndex;\n                    index++\n                ) {\n                    const event = events[index];\n                    const type = event.value.type.trim();\n\n                    if (type === "resume") {\n                        continue;\n                    }\n\n                    const next = events[index + 1];\n\n                    if (!next) {\n                        return false;\n                    }\n\n                    const attributes = {\n                        ...event.value\n                    };\n                    delete attributes.type;\n\n                    if (!this.overwrite({\n                        type,\n                        startTime: event.time,\n                        endTime: next.time,\n                        otherAttributes: attributes\n                    })) {\n                        return false;\n                    }\n                }\n\n                return true;\n            }\n            catch {\n                return false;\n            }\n        }\n\n        get status() {'''
if needle not in s: raise SystemExit('anchor not found')
s=s.replace(needle,insert,1)
